1	import { readFileSync } from "node:fs";
2	import { join } from "node:path";
3	import { describe, expect, it } from "vitest";
4	import {
5		classifyConsonant,
6		expectedAspiration,
7		HIGH_CLASS_CONSONANTS,
8		UNCLASSIFIED,
9	} from "./soundType";
10	import { consonants, getConsonant, ThaiSymbolClass } from "./symbols";
11	
12	const SOUND_TYPES = [
13		"sonorant",
14		"unaspirated-obstruent",
15		"aspirate-or-fricative",
16	];
17	
18	describe("sound-type classification (the derivable class rule)", () => {
19		// AC1
20		it("classifies all 44 consonants and derives the declared class for each", () => {
21			expect(consonants).toHaveLength(44);
22	
23			const bucketCounts = new Map<string, number>();
24			for (const consonant of consonants) {
25				const result = classifyConsonant(consonant);
26				expect(
27					result.state,
28					`${consonant.character}: ${
29						result.state === "unclassifiable" ? result.reason : ""
30					}`,
31				).toBe("classified");
32				if (result.state !== "classified") continue;
33	
34				expect(SOUND_TYPES).toContain(result.soundType);
35				expect(result.consonantClass, consonant.character).toBe(
36					consonant.classType,
37				);
38				bucketCounts.set(
39					result.soundType,
40					(bucketCounts.get(result.soundType) ?? 0) + 1,
41				);
42			}
43	
44			// The phase's own arithmetic: 10 sonorants, 9 unaspirated obstruents
45			// (including silent อ), 25 aspirates and fricatives.
46			expect(bucketCounts.get("sonorant")).toBe(10);
47			expect(bucketCounts.get("unaspirated-obstruent")).toBe(9);
48			expect(bucketCounts.get("aspirate-or-fricative")).toBe(25);
49		});
50	
51		// AC1 — the derivation is independent of what it is checked against: the
52		// module never touches the declared class field, so the agreement above
53		// is a real measurement rather than true by construction.
54		it("derives without reading the declared class field", () => {
55			const source = readFileSync(
56				join(import.meta.dirname, "soundType.ts"),
57				"utf8",
58			);
59			expect(source).not.toMatch(/classType/);
60		});
61	
62		// AC2
63		it("isAspirated agrees with initialSound for all 44 — ฑ and ฒ included", () => {
64			for (const consonant of consonants) {
65				expect(
66					consonant.isAspirated,
67					`${consonant.character} (${consonant.initialSound})`,
68				).toBe(expectedAspiration(consonant.initialSound));
69			}
70	
71			// The two letters that shipped disagreeing with their own initialSound.
72			expect(getConsonant("ฑ")?.isAspirated).toBe(true);
73			expect(getConsonant("ฒ")?.isAspirated).toBe(true);
74		});
75	
76		// AC3 — the first two buckets consult no per-letter table: a glyph the
77		// repository has never seen classifies from its sound facts alone.
78		it("derives the sonorant and unaspirated buckets from sound alone", () => {
79			expect(
80				classifyConsonant({
81					character: "✘",
82					initialSound: "ng (entirely made up)",
83					isAspirated: false,
84				}),
85			).toEqual({
86				state: "classified",
87				soundType: "sonorant",
88				consonantClass: ThaiSymbolClass.Low,
89			});
90	
91			expect(
92				classifyConsonant({
93					character: "✘",
94					initialSound: "bp (entirely made up)",
95					isAspirated: false,
96				}),
97			).toEqual({
98				state: "classified",
99				soundType: "unaspirated-obstruent",
100				consonantClass: ThaiSymbolClass.Mid,
101			});
102	
103			expect(
104				classifyConsonant({
105					character: "✘",
106					initialSound: "silent (entirely made up)",
107					isAspirated: false,
108				}),
109			).toEqual({
110				state: "classified",
111				soundType: "unaspirated-obstruent",
112				consonantClass: ThaiSymbolClass.Mid,
113			});
114		});
115	
116		// AC3 — only the aspirate/fricative bucket consults a list, and the list
117		// is the irreducible 11-member residue.
118		it("memorises exactly the 11 high aspirates and fricatives, nothing else", () => {
119			expect(HIGH_CLASS_CONSONANTS).toHaveLength(11);
120	
121			for (const character of HIGH_CLASS_CONSONANTS) {
122				const consonant = getConsonant(character);
123				expect(consonant, character).toBeDefined();
124				if (!consonant) continue;
125				const result = classifyConsonant(consonant);
126				expect(result.state, character).toBe("classified");
127				if (result.state !== "classified") continue;
128				// No sonorant and no unaspirated obstruent appears in the list.
129				expect(result.soundType, character).toBe("aspirate-or-fricative");
130			}
131	
132			// The list is exactly the declared high class — nothing missing (ศ
133			// stays in on measurement), nothing extra.
134			const declaredHigh = consonants
135				.filter((consonant) => consonant.classType === ThaiSymbolClass.High)
136				.map((consonant) => consonant.character);
137			expect([...HIGH_CLASS_CONSONANTS].sort()).toEqual(declaredHigh.sort());
138		});
139	});
140	
141	describe("the three classification states", () => {
142		// AC8 — state one: classified.
143		it("reports a real consonant as classified", () => {
144			const maaw = getConsonant("ม");
145			expect(maaw).toBeDefined();
146			if (!maaw) return;
147			expect(classifyConsonant(maaw).state).toBe("classified");
148		});
149	
150		// AC8 — state two: unclassifiable, and never disguised as unclassified.
151		it("reports a letter the rule cannot place as unclassifiable, with the reason", () => {
152			const unknown = classifyConsonant({
153				character: "✘",
154				initialSound: "zz (no such onset)",
155				isAspirated: false,
156			});
157			expect(unknown.state).toBe("unclassifiable");
158			expect(unknown.state).not.toBe("unclassified");
159			if (unknown.state !== "unclassifiable") return;
160			expect(unknown.reason).toContain("zz");
161	
162			// The exact shape ฑ shipped in: an initialSound naming an aspirated
163			// stop over isAspirated: false is a contradiction, not a bucket.
164			const contradiction = classifyConsonant({
165				character: "ฑ",
166				initialSound: "th (usually same as ท, sometimes d)",
167				isAspirated: false,
168			});
169			expect(contradiction.state).toBe("unclassifiable");
170			if (contradiction.state !== "unclassifiable") return;
171			expect(contradiction.reason).toContain("isAspirated");
172		});
173	
174		// AC8 — state three: not yet classified, distinct from the other two.
175		it("keeps not-yet-classified a distinct third state", () => {
176			expect(UNCLASSIFIED.state).toBe("unclassified");
177	
178			const maaw = getConsonant("ม");
179			if (!maaw) return;
180			const states = new Set([
181				classifyConsonant(maaw).state,
182				classifyConsonant({
183					character: "✘",
184					initialSound: "zz",
185					isAspirated: false,
186				}).state,
187				UNCLASSIFIED.state,
188			]);
189			expect(states.size).toBe(3);
190		});
191	});
192

