358	// ----------------------------------------------------------------------------
359	// Final-sound behaviour
360	// ----------------------------------------------------------------------------
361	
362	export type FinalSoundBehaviour =
363		| { kind: "final"; sound: string }
364		| { kind: "vowel-syllable"; syllable: "live" | "dead" }
365		| { kind: "not-applicable" };
366	
367	// Short vowels whose open syllable is nonetheless live, because the vowel
368	// carries its own sonorant ending: ำ ends in m, ไ and ใ in the i glide, เ-า
369	// in the o glide. Everything else derives from length: long open syllables
370	// are live, short ones dead.
371	const LIVE_SHORT_VOWELS: readonly string[] = ["ำ", "ไ", "ใ", "เ-า"];
372	
373	function openSyllableLiveness(vowel: ThaiVowel): "live" | "dead" {
374		if (vowel.length === "long") return "live";
375		return LIVE_SHORT_VOWELS.includes(vowel.character) ? "live" : "dead";
376	}
377	
378	// ----------------------------------------------------------------------------
379	// The annotation record
380	// ----------------------------------------------------------------------------
381	
382	export type AnnotationKind = "consonant" | "vowel" | "tone-mark" | "word";
383	
384	export interface SceneAnnotation {
385		kind: AnnotationKind;
386		/** ThaiSymbol.character, or the Thai spelling for a word record. */
387		key: string;
388		romanizedName: string;
389		finalSound: FinalSoundBehaviour;
390		/** Sound-type classification; null where the kind has no class at all. */
391		classification: Classification | null;
392		/** Class district; null for kinds that must not cue a class. */
393		district: District | null;
394		/** The mnemonic's shape binding. Task 2.4 authors these. */
395		shapeCue: string | null;
396		/** The mnemonic's sound binding. Task 2.4 authors these. */
397		soundCue: string | null;
398		carriesTone: boolean;
399		/** One of the five shipped motions, named — never contour data. */
400		toneMotion: ToneValue | null;
401		conditionalForm: ConditionalVowelForm | null;
402	}
403	
404	function consonantAnnotation(consonant: ThaiConsonant): SceneAnnotation {
405		const classification = classifyConsonant(consonant);
406		return {
407			kind: "consonant",
408			key: consonant.character,
409			romanizedName: consonant.nameRomanized,
410			finalSound: { kind: "final", sound: consonant.finalSound },
411			classification,
412			district:
413				classification.state === "classified"
414					? districtForClass(classification.consonantClass)
415					: null,
416			shapeCue: null,
417			soundCue: null,
418			carriesTone: false,
419			toneMotion: null,
420			conditionalForm: null,
421		};
422	}
423	
424	function vowelAnnotation(vowel: ThaiVowel): SceneAnnotation {
425		return {
426			kind: "vowel",
427			key: vowel.character,
428			romanizedName: vowel.name,
429			finalSound: {
430				kind: "vowel-syllable",
431				syllable: openSyllableLiveness(vowel),
432			},
433			classification: null,
434			district: null,
435			shapeCue: null,
436			soundCue: null,
437			carriesTone: false,
438			toneMotion: null,
439			conditionalForm: conditionalFormFor(vowel.character),
440		};
441	}
