443	function toneMarkAnnotation(mark: ThaiToneMark): SceneAnnotation {
444		return {
445			kind: "tone-mark",
446			key: mark.character,
447			romanizedName: mark.name,
448			finalSound: { kind: "not-applicable" },
449			classification: null,
450			district: null,
451			shapeCue: null,
452			soundCue: null,
453			carriesTone: true,
454			// The mark's citation motion is its mid-class effect — the tone it is
455			// named for. The full class-dependent table stays on ThaiToneMark.
456			toneMotion: mark.midClassTone,
457			conditionalForm: null,
458		};
459	}
460	
461	function wordAnnotation(word: ThaiWord): SceneAnnotation {
462		return {
463			kind: "word",
464			key: word.name,
465			romanizedName: word.romanization,
466			finalSound: { kind: "not-applicable" },
467			classification: null,
468			district: null,
469			shapeCue: null,
470			soundCue: null,
471			carriesTone: true,
472			toneMotion: word.tone,
473			conditionalForm: null,
474		};
