477	/**
478	 * One annotation per mnemonic-carrying record in symbols.ts: 44 consonants,
479	 * 29 vowels, 4 tone marks, and the mnemonic-bearing words — 82 in all. The
480	 * word and tone-mark records are the nine whose facts have no other home.
481	 */
482	export const sceneAnnotations: readonly SceneAnnotation[] = [
483		...consonants.map(consonantAnnotation),
484		...vowels.map(vowelAnnotation),
485		...toneMarks.map(toneMarkAnnotation),
486		...words.filter((word) => word.mnemonic !== undefined).map(wordAnnotation),
487	];
488	
489	const annotationsByKey = new Map(
490		sceneAnnotations.map((annotation) => [annotation.key, annotation]),
491	);
492	
493	export function annotationFor(key: string): SceneAnnotation | undefined {
494		return annotationsByKey.get(key);
495	}
496	
497	// ----------------------------------------------------------------------------
498	// Validation
499	// ----------------------------------------------------------------------------
500	// Failures name their fields. A refused record must never look like an empty
501	// one — the caller gets the exact list of what is missing and what is wrong.
502	
503	export type Validation =
504		| { ok: true }
505		| { ok: false; missing: readonly string[]; invalid: readonly string[] };
506	
507	function verdict(missing: string[], invalid: string[]): Validation {
508		return missing.length === 0 && invalid.length === 0
509			? { ok: true }
510			: { ok: false, missing, invalid };
511	}
512	
513	function isBlank(value: string | null | undefined): boolean {
514		return value === null || value === undefined || value.trim() === "";
515	}
516	
517	/** The loosely-typed shape validation accepts, so deficient records can be checked. */
518	export interface SceneAnnotationInput {
519		kind: AnnotationKind;
520		district?: District | null;
521		shapeCue?: string | null;
522		soundCue?: string | null;
523		carriesTone?: boolean;
524		toneMotion?: ToneValue | null;
525	}
526	
527	/**
528	 * A record validates only if it binds shape and sound as separate cues, its
529	 * district where it carries a class, and its tone motion where it carries a
530	 * tone. A record binding only shape fails, naming the missing fields.
531	 */
532	export function validateSceneAnnotation(
533		record: SceneAnnotationInput,
534	): Validation {
535		const missing: string[] = [];
536		const invalid: string[] = [];
537	
538		if (isBlank(record.shapeCue)) missing.push("shapeCue");
539		if (isBlank(record.soundCue)) missing.push("soundCue");
540	
541		if (record.kind === "consonant") {
542			if (!record.district) missing.push("district");
543		} else if (record.district) {
544			invalid.push(
545				"district: only a class-bearing record stages in a class district",
546			);
547		}
548	
549		if (record.carriesTone) {
550			if (!record.toneMotion) missing.push("toneMotion");
551		} else if (record.toneMotion) {
552			invalid.push("toneMotion: only a tone-carrying record encodes a motion");
553		}
554	
555		return verdict(missing, invalid);
556	}
557	
558	export function validateConditionalForm(form: {
559		vowel?: string;
560		openForm?: string;
561		withFinalForm?: string;
562	}): Validation {
563		const missing: string[] = [];
564		const invalid: string[] = [];
565	
566		if (isBlank(form.vowel)) missing.push("vowel");
567		if (isBlank(form.openForm)) missing.push("openForm");
568		if (isBlank(form.withFinalForm)) missing.push("withFinalForm");
