1	import { readdirSync, readFileSync } from "node:fs";
2	import { join } from "node:path";
3	import { describe, expect, it } from "vitest";
4	import {
5		annotationFor,
6		conditionalVowelForms,
7		confusablePairs,
8		DISTINGUISHING_FEATURES,
9		districtForClass,
10		sceneAnnotations,
11		TONE_MOTION_EXPORT,
12		TONE_MOTION_SOURCE,
13		validateConditionalForm,
14		validateConfusablePair,
15		validateSceneAnnotation,
16	} from "./sceneGrammar";
17	import { consonants, getThaiSymbol, vowels } from "./symbols";
18	
19	const REPO_ROOT = join(import.meta.dirname, "..", "..", "..", "..");
20	const SRC_ROOT = join(REPO_ROOT, "src");
21	
22	function sourceFiles(dir: string): string[] {
23		return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
24			const path = join(dir, entry.name);
25			if (entry.isDirectory()) return sourceFiles(path);
26			if (!/\.tsx?$/.test(entry.name)) return [];
27			if (/\.test\.tsx?$/.test(entry.name)) return [];
28			return [path];
29		});
30	}
31	
32	describe("conditional vowel forms are fields, not prose", () => {
33		// AC4
34		it("declares both written forms for every vowel whose form changes", () => {
35			// The floor: the form changes this repository's own prose records —
36			// dropping any of these silently would re-trap the rule in prose.
37			const proseStated = ["ะ", "เ-ะ", "เ-อ", "เ-อะ", "-ัว", " ื", "โ-ะ"];
38			const declared = conditionalVowelForms.map((form) => form.vowel);
39			for (const vowel of proseStated) {
