				<SymbolInfoRow label="Initial sound" value={c.initialSound} />
				<SymbolInfoRow label="Final sound" value={c.finalSound} />
				<SymbolInfoRow
					label="Ending type"
					value={c.hasDeadEnding ? "Dead" : "Live"}
					valueStyle={{
						color: c.hasDeadEnding
							? "var(--color-danger)"
							: "var(--color-master)",
					}}
				/>

