22	/**
23	 * Task 2.5's proof: the opening band, and the lesson that turns consonant
24	 * class from 44 memorised facts into two audible buckets plus a small residue.
25	 *
26	 * The band is six decks — the five this task authors (lessons 02-05 and
27	 * `lesson-sound-buckets`) plus `lesson-01` from task 1.4, which every check
28	 * here sweeps too, because "no symbol is used before it is taught" is a claim
29	 * about the band as a sequence and cannot be made one lesson at a time.
30	 *
31	 * Everything here reads the *committed* decks under `public/lessons/`, not a
32	 * fixture — the artefacts the app serves are the artefacts under test. The
33	 * lesson's rule is likewise read off the deck rather than restated here: the
34	 * third bucket's members come out of the slide that names them, so a lesson
35	 * that stopped naming one would stop being able to place it.
36	 */
37	
38	const REPO_ROOT = join(import.meta.dirname, "..", "..", "..", "..");
39	const PUBLIC_LESSONS = join(REPO_ROOT, "public", "lessons");
40	const SCRIPTS = join(REPO_ROOT, "content", "lessons");
41	
42	/** The slide whose body states which third-bucket letters are known so far. */
43	const THIRD_BUCKET_SLIDE = "bucket-three";
44	const BUCKETS_LESSON_ID = "lesson-sound-buckets";
45	/**
46	 * The first lesson still on the licensed video arm — the live end of the
47	 * strangler seam, which this test watches to prove the seam has two sides.
48	 *
49	 * It was `lesson-06` while the opening band was the only in-house band. Task
50	 * 3.3 moved lessons 06-11 onto the deck arm, so the video side now begins at
51	 * `lesson-12`; it moves again each time a later band is produced, and the
52	 * claim being made here is unchanged.
53	 */
54	
55	interface BandLesson {
56		readonly id: string;
57		/**
58		 * The `lessons`-table row this deck teaches, where there is one.
59		 * `lesson-sound-buckets` has none: it introduces no symbol, so it declares
60		 * no row, and the sequence entry that would give it one is owned by
61		 * `lessonSequence.ts` (see the note on `describe("the content seam")`).
62		 */
63		readonly legacyNumber?: number;
64	}
65	
66	/** Declaration order is the order the learner meets them. */
67	const BAND: readonly BandLesson[] = [
68		{ id: "lesson-01", legacyNumber: 1 },
69		{ id: "lesson-02", legacyNumber: 2 },
70		{ id: "lesson-03", legacyNumber: 3 },
71		{ id: "lesson-04", legacyNumber: 4 },
72		{ id: "lesson-05", legacyNumber: 5 },
73		{ id: BUCKETS_LESSON_ID },
74	];
75	
76	type RawSlide = {
77		kind: string;
78		id: string;
79		heading?: string;
80		body?: string[];
81		prompt?: string;
82		answers?: string[];
83		revealSlideId?: string;
84		retrievalSlideId?: string;
85		audio?: string[];
86		image?: string;
87	};
88	type RawDeck = {
89		lessonId: string;
90		title: string;
91		slides: RawSlide[];
92		teachingWords?: { thai: string; reason: string }[];
93	};
94	type Manifest = { lessonId: string; assets: { path: string | null }[] };
95	
96	const THAI = /[฀-๿]/g;
97	const THAI_RUN = /[฀-๿]+/g;
98	
99	function lessonDir(id: string): string {
100		return join(PUBLIC_LESSONS, id);
101	}
102	
103	function readDeck(id: string): RawDeck {
104		return JSON.parse(
105			readFileSync(join(lessonDir(id), "deck.json"), "utf-8"),
106		) as RawDeck;
107	}
108	
109	function readManifest(id: string): Manifest {
110		return JSON.parse(
111			readFileSync(join(lessonDir(id), "manifest.json"), "utf-8"),
112		) as Manifest;
113	}
114	
115	/** Every piece of learner-facing prose on a deck, in slide order. */
116	function textsOf(deck: RawDeck): string[] {
117		const texts: string[] = [deck.title];
118		for (const slide of deck.slides) {
119			if (slide.heading) texts.push(slide.heading);
120			if (slide.prompt) texts.push(slide.prompt);
121			texts.push(...(slide.body ?? []));
122			texts.push(...(slide.answers ?? []));
123		}
124		return texts;
125	}
126	
127	function thaiCharsIn(texts: readonly string[]): Set<string> {
128		const chars = new Set<string>();
129		for (const text of texts)
130			for (const ch of text.match(THAI) ?? []) chars.add(ch);
131		return chars;
132	}
133	
134	/** Runs of two or more Thai characters — words, as opposed to bare letters. */
135	function thaiWordsIn(texts: readonly string[]): Set<string> {
136		const words = new Set<string>();
137		for (const text of texts) {
138			for (const run of text.match(THAI_RUN) ?? []) {
139				if (run.length >= 2) words.add(run);
140			}
141		}
142		return words;
143	}
144	
145	/**
146	 * Symbols a `lessons` row declares. The table stores combining vowels with a
147	 * dotted-circle-free leading space (`" ี"`), so the Thai characters are pulled
148	 * out rather than the strings compared.
149	 */
150	function declaredSymbols(legacyNumber: number | undefined): Set<string> {
151		// Three outcomes, not two. No `legacyNumber` means the lesson declares no
152		// row at all (`lesson-sound-buckets`) and legitimately introduces nothing.
153		// A `legacyNumber` whose row is missing is a broken band table, and it must
154		// not arrive here as the same empty set: that would quietly make AC2's
155		// "uses everything it declares" loop vacuous for that lesson.
156		if (legacyNumber === undefined) return new Set();
157		const row = lessons.find((lesson) => lesson.number === legacyNumber);
158		if (!row) {
159			throw new Error(
160				`the band names lesson ${legacyNumber}, which the lessons table does not declare`,
161			);
162		}
163		return thaiCharsIn([...row.consonants, ...row.vowels]);
164	}
165	
166	/**
167	 * Symbols a lesson shows without teaching, declared in its script's own
168	 * comment block as `previews: <glyph> — <why>`. A deck may only reach outside
169	 * the taught set through one of these, and a declaration with no reason does
170	 * not count — which is what stops "previews:" becoming a blanket exemption.
171	 */
172	function declaredPreviews(id: string): Set<string> {
173		const source = readFileSync(join(SCRIPTS, `${id}.md`), "utf-8");
174		const previews = new Set<string>();
175		for (const line of source.matchAll(/^previews:\s*(.+)$/gm)) {
176			const body = line[1];
177			if (body.trim() === "none") continue;
178			const [glyphs, ...rest] = body.split("—");
179			if (rest.join("—").trim().length === 0) continue;
180			for (const ch of glyphs.match(THAI) ?? []) previews.add(ch);
181		}
182		return previews;
183	}
184	
185	/** Sentences, split only on terminal punctuation so a clause keeps its glyphs. */
186	function sentencesOf(text: string): string[] {
187		return text
188			.split(/(?<=[.?!])\s+/)
189			.map((s) => s.trim())
190			.filter((s) => s.length > 0);
191	}
192	
193	/**
194	 * Does this sentence assign a consonant class? Both channels count: the words
195	 * "low/mid/high class", and the three district names, because a district *is*
196	 * the class said without the word (sceneGrammar.ts).
197	 */
198	const CLASS_CLAIM =
199		/\b(?:low|mid|high)[\s-]?class\b|\b(?:temple|market|harbor)\b/i;
200	
201	const vocabulary = vocabularyData as unknown as VocabEntry[];
202	const vocabularyByThai = new Set(vocabulary.map((entry) => entry.thai));
203	
204	const decks = new Map(BAND.map((lesson) => [lesson.id, readDeck(lesson.id)]));
205	
206	/**
207	 * Every symbol the band has taught by the end of each of its lessons —
208	 * vowels as well as consonants, since AC2 governs both. `consonantsTaughtInBand`
209	 * narrows it to the consonants where a check needs only those.
210	 */
211	const taughtAfter = new Map<string, Set<string>>();
212	{
213		const running = new Set<string>();
214		for (const lesson of BAND) {
215			for (const ch of declaredSymbols(lesson.legacyNumber)) running.add(ch);
216			taughtAfter.set(lesson.id, new Set(running));
217		}
218	}
219	
220	const consonantsTaughtInBand = [...(taughtAfter.get(BUCKETS_LESSON_ID) ?? [])]
221		.map((ch) => consonants.find((c) => c.character === ch))
222		.filter((c): c is ThaiConsonant => c !== undefined);
