224	// ============================================================================
225	// The rule, as the lesson states it
226	// ============================================================================
227	
228	type StatedRuleOutcome =
229		| { placed: true; consonantClass: ThaiSymbolClass; bucket: string }
230		| { placed: false; reason: string };
231	
232	/**
233	 * Apply the derivable-buckets rule exactly as `lesson-sound-buckets` states
234	 * it. Buckets one and two come from the sound alone — `classifyConsonant`'s
235	 * own derivation, which reads `initialSound` and `isAspirated` and no table.
236	 * The third bucket is deliberately *not* derived: the lesson defers the split
237	 * and names the letters it has already taught, so this consults that list and
238	 * nothing else. A letter the lesson never names comes back unplaced.
239	 */
240	function classFromStatedRule(
241		symbol: ThaiConsonant,
242		namedLowInThirdBucket: ReadonlySet<string>,
243	): StatedRuleOutcome {
244		const sound = classifyConsonant({
245			character: symbol.character,
246			initialSound: symbol.initialSound,
247			isAspirated: symbol.isAspirated,
248		});
249		if (sound.state !== "classified") {
250			return { placed: false, reason: sound.reason };
251		}
252		if (sound.soundType === "sonorant") {
253			return {
254				placed: true,
255				consonantClass: ThaiSymbolClass.Low,
256				bucket: "one — it can be hummed",
257			};
258		}
259		if (sound.soundType === "unaspirated-obstruent") {
260			return {
261				placed: true,
262				consonantClass: ThaiSymbolClass.Mid,
263				bucket: "two — it stops and releases no breath",
264			};
265		}
266		if (namedLowInThirdBucket.has(symbol.character)) {
267			return {
268				placed: true,
269				consonantClass: ThaiSymbolClass.Low,
270				bucket: "three — the lesson names it among the ones met so far",
271			};
272		}
273		return {
274			placed: false,
275			reason: `bucket three, and the lesson presents nothing that places ${symbol.character}`,
276		};
277	}
278	
279	/** The third-bucket letters the buckets lesson itself claims are low class. */
280	function namedLowInThirdBucket(): Set<string> {
281		const deck = decks.get(BUCKETS_LESSON_ID);
282		const slide = deck?.slides.find((s) => s.id === THIRD_BUCKET_SLIDE);
283		// An absent slide is not a lesson that names nobody. Both would return an
284		// empty set and fail AC3, but only one of them is diagnosed correctly by
285		// "the lesson presents nothing that places ช" — the other is a renamed
286		// slide id, and it says so here instead of four letters down.
287		if (!slide) {
288			throw new Error(
289				`${BUCKETS_LESSON_ID} has no "${THIRD_BUCKET_SLIDE}" slide, so the rule it states cannot be read off the deck`,
290			);
291		}
292		const named = new Set<string>();
293		for (const text of slide.body ?? []) {
294			for (const sentence of sentencesOf(text)) {
295				if (!/low[\s-]?class/i.test(sentence)) continue;
296				for (const ch of sentence.match(THAI) ?? []) named.add(ch);
297			}
298		}
299		return named;
300	}
