579					const files = readdirSync(join(lessonDir(lesson.id), entry));
580					for (const file of files) {
581						const url = `/thai-script/lessons/${lesson.id}/${entry}/${file}`;
582						expect(
583							referenced.has(url),
584							`${lesson.id}: ${url} is on disk but nothing references it`,
585						).toBe(true);
586					}
587				}
588			}
589		});
590	});
591	
592	describe("the band's retrieval practice", () => {
593		it("asks the learner to attempt an answer before every reveal, on every band deck", () => {
594			for (const lesson of BAND) {
595				const deck = decks.get(lesson.id);
596				expect(deck, lesson.id).toBeDefined();
597				if (!deck) continue;
598	
599				const retrievals = deck.slides.filter((s) => s.kind === "retrieval");
600				const reveals = deck.slides.filter((s) => s.kind === "reveal");
601				expect(
602					retrievals.length,
603					`${lesson.id} has no retrieval step`,
604				).toBeGreaterThan(0);
605				expect(reveals.length, lesson.id).toBe(retrievals.length);
606	
607				const seen = new Set<string>();
608				for (const slide of deck.slides) {
609					if (slide.kind === "retrieval") {
610						seen.add(slide.id);
611						// The prompt must not carry its own answer.
612						expect(slide.revealSlideId, `${lesson.id}/${slide.id}`).toBeTruthy();
613						expect("answers" in slide, `${lesson.id}/${slide.id}`).toBe(false);
614						continue;
615					}
616					if (slide.kind !== "reveal") continue;
617					expect(
618						seen.has(slide.retrievalSlideId ?? ""),
619						`${lesson.id}: reveal ${slide.id} comes before the retrieval it answers`,
620					).toBe(true);
621				}
622			}
623		});
624	});
